(()=>{'use strict';if(document.getElementById('wdea-ai-panel'))return;const base=document.baseURI;const asset=n=>n==='wdea-robot-blue.png'?'data:image/png;base64,':new URL(n,base).href;let mode='chat',recognizer=null,dragged=false,recording=false,history=[];try{history=JSON.parse(localStorage.getItem('wdea_ai_chat_v1')||'[]')}catch(e){}const $=s=>document.querySelector(s);const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const float=document.createElement('div');float.id='wdea-companion';float.setAttribute('role','button');float.setAttribute('tabindex','0');float.setAttribute('aria-label','WDEA AI megnyitása');float.innerHTML='<img alt="WDEA AI karakter" src="'+asset('wdea-robot-blue.png')+'">';document.body.append(float);const launch=document.createElement('button');launch.id='wdea-ai-launch';launch.textContent='✦ WDEA AI';document.body.append(launch);const panel=document.createElement('section');panel.id='wdea-ai-panel';panel.setAttribute('aria-label','WDEA AI asszisztens');panel.innerHTML='<div class="wdea-head"><div><strong>✦ WDEA <span style="color:#12baff">AI</span></strong><div class="wdea-note">WORK asszisztens · helyi parancsok</div></div><button id="wdea-close" aria-label="Bezárás">✕</button></div><div class="wdea-tabs"><button data-mode="chat">Írás</button><button data-mode="voice">Hang</button><button data-mode="image">Kép</button><button data-mode="tools">Eszközök</button></div><div class="wdea-content" id="wdea-body"></div><form class="wdea-compose" id="wdea-form"><input id="wdea-input" placeholder="Írj az AI-nak…" autocomplete="off"><button type="button" id="wdea-mic" aria-label="Beszédfelismerés">🎙</button><button type="submit">➤</button></form>';document.body.append(panel);const body=$('#wdea-body');function open(){float.classList.remove('wdea-edge-away');document.body.classList.remove('wdea-robot-parked');panel.classList.add('open');render();}function close(){panel.classList.add('wdea-folding');setTimeout(()=>{panel.classList.remove('open','wdea-folding')},320);}launch.onclick=open;float.onclick=()=>{if(!dragged)open();dragged=false};float.onkeydown=e=>{if(e.key==='Enter')open()};$('#wdea-close').onclick=close;document.querySelectorAll('#wdea-ai-panel [data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;render()});function say(t){if(typeof window.wdeaSpeakCustom==='function'){return window.wdeaSpeakCustom(t,true)}return Promise.resolve(false)}function add(role,t){history.push({role,text:t});history=history.slice(-70);try{localStorage.setItem('wdea_ai_chat_v1',JSON.stringify(history))}catch(e){}render()}function answer(q){const s=q.toLocaleLowerCase('hu');if(/szia|hello|üdv/.test(s))return'Szia! A WDEA WORK helyi asszisztense vagyok. Megnyithatom a felületet és segíthetek a navigációban.';if(/profil|beállítás/.test(s)){const el=[...document.querySelectorAll('button,a')].find(x=>/profil|beállítás/i.test(x.textContent||''));if(el){el.click();return'Megnyitottam a megfelelő menüpontot.'}return'Ezt a menüpontot ezen a nézeten nem találtam.'}if(/keres/.test(s)){const el=[...document.querySelectorAll('button,a')].find(x=>/keresés|kereső/i.test(x.textContent||''));if(el){el.click();return'Megnyitottam a keresést.'}return'A kereső jelenleg nem érhető el ezen a nézeten.'}if(/coin|gyémánt|pont/.test(s))return'A WDEA Coin és Diamond modul külön pénzügyi jogosultságokkal működik. A 10 eurós minimum kifizetés tervezési követelmény; tényleges kifizetést ez a helyi felület nem indít.';if(/hang|beszélj|olvasd/.test(s))return'A hangos felolvasást a telefon beszédmotorja végzi. A mikrofon gombbal indíthatod a felismerést, ha a böngésző támogatja.';return'Ezt a kérdést a jelenlegi helyi parancsmotor még nem tudja megbízhatóan megválaszolni. A DRIVE AI modelljének tényleges összekapcsolása szükséges. Nem adok kitalált választ.'}function send(q){q=(q||'').trim();if(!q)return;document.dispatchEvent(new CustomEvent('wdea-ai-command',{detail:{text:q}}));add('user',q);float.dataset.state='thinking';setTimeout(()=>{let r=answer(q);add('ai',r);float.dataset.state='idle';if(localStorage.getItem('wdea_speak_enabled')==='1')say(r)},320)}$('#wdea-form').onsubmit=e=>{e.preventDefault();const input=$('#wdea-input');const v=input.value;input.value='';send(v)};function mic(){if(recording){try{recognizer&&recognizer.abort()}catch(e){}recording=false;float.dataset.state='idle';render();return}const R=window.SpeechRecognition||window.webkitSpeechRecognition;if(!R){add('ai','Ez a böngésző nem támogatja a beszédfelismerést. A hangos felolvasás ettől még működhet.');return}try{recognizer=new R();recognizer.lang='hu-HU';recognizer.interimResults=false;recognizer.onresult=e=>send(e.results[0][0].transcript);recognizer.onerror=e=>add('ai','Mikrofonhiba: '+e.error);recognizer.onend=()=>{recording=false;float.dataset.state='idle';render()};recognizer.start();recording=true;float.dataset.state='thinking';render()}catch(e){add('ai','A mikrofon nem indult: '+e.message)}}$('#wdea-mic').onclick=mic;function render(){document.querySelectorAll('#wdea-ai-panel [data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));if(mode==='chat'){body.innerHTML='<div class="wdea-note">A chat jelenleg ellenőrzött helyi parancsokat kezel, nem teljes nyelvi modell.</div>'+history.map((m,i)=>'<div class="wdea-msg '+(m.role==='user'?'user':'')+'"><div class="wdea-msg-text">'+safe(m.text)+'</div><button type="button" class="wdea-read-aloud" data-read-index="'+i+'" aria-label="Üzenet felolvasása" title="Üzenet felolvasása">🔊 <span>Felolvasás</span></button></div>').join('')+'<label class="wdea-note"><input type="checkbox" id="wdea-speak" '+(localStorage.getItem('wdea_speak_enabled')==='1'?'checked':'')+'> Válaszok felolvasása</label>';body.querySelectorAll('[data-read-index]').forEach(btn=>btn.onclick=()=>{const m=history[Number(btn.dataset.readIndex)];if(m&&m.text)say(m.text)});const speakToggle=body.querySelector('#wdea-speak');if(speakToggle)speakToggle.onchange=()=>{try{localStorage.setItem('wdea_speak_enabled',speakToggle.checked?'1':'0')}catch(e){}if(!speakToggle.checked&&window.speechSynthesis)window.speechSynthesis.cancel()};body.scrollTop=body.scrollHeight}else if(mode==='voice'){body.innerHTML='<div class="wdea-orb">🎙</div><div style="text-align:center">'+(recording?'Hallgatlak…':'Érintsd meg a mikrofont a beszédhez')+'</div><div class="wdea-note" style="text-align:center;margin:16px">A telefon mikrofonját és hangszóróját használja. A felismerés böngészőtől függ, és külső szolgáltatást is igénybe vehet.</div><button id="wdea-voice-start" style="width:100%">'+(recording?'⏹ Mikrofon kikapcsolása':'🎙 Mikrofon indítása')+'</button><button id="wdea-voice-test" style="width:100%;margin-top:9px">🔊 Hang tesztelése</button>';$('#wdea-voice-start').onclick=mic;$('#wdea-voice-test').onclick=()=>say('Szia! Én vagyok a WDEA AI. Hallasz engem?')}else if(mode==='image'){body.innerHTML='<div class="wdea-note">Kép feltöltése és előnézete. A tényleges termékfelismerés és OCR szervermodellhez kötése még szükséges.</div><input type="file" id="wdea-file" accept="image/*" style="width:100%;margin:12px 0"><div id="wdea-preview"></div>';$('#wdea-file').onchange=e=>{const f=e.target.files[0];if(!f)return;const url=URL.createObjectURL(f);$('#wdea-preview').innerHTML='<img style="width:100%;border-radius:12px" alt="Feltöltött kép" src="'+url+'"><p class="wdea-note">Fájl: '+safe(f.name)+' — felismerési eredményt modellkapcsolat nélkül nem állítunk elő.</p>'}}else{const items=[['✍️ Szövegkészítés','bejegyzés'],['🛍 Termékek','termék'],['🔎 Keresés','keresés'],['📊 Elemzés','statisztika'],['💬 Üzenetek','üzenet'],['⚙️ Rendszersúgó','beállítás']];body.innerHTML='<div class="wdea-grid">'+items.map(x=>'<button class="wdea-tool" data-query="'+x[1]+'">'+x[0]+'<div class="wdea-note">WORK funkció</div></button>').join('')+'</div><p class="wdea-note">Az eszközök a WORK meglévő menüpontjaira irányítanak, ha elérhetők. Nem jelentenek kész szerveroldali AI-funkciókat.</p>';body.querySelectorAll('[data-query]').forEach(b=>b.onclick=()=>{mode='chat';send('Nyisd meg: '+b.dataset.query)})}}const start={x:0,y:0,left:0,top:0};float.addEventListener('pointerdown',e=>{start.x=e.clientX;start.y=e.clientY;const r=float.getBoundingClientRect();start.left=r.left;start.top=r.top;dragged=false;float.setPointerCapture(e.pointerId)});float.addEventListener('pointermove',e=>{if(!float.hasPointerCapture(e.pointerId))return;const dx=e.clientX-start.x,dy=e.clientY-start.y;if(Math.abs(dx)+Math.abs(dy)>8)dragged=true;if(!dragged)return;float.style.left=Math.max(0,Math.min(innerWidth-75,start.left+dx))+'px';float.style.top=Math.max(0,Math.min(innerHeight-90,start.top+dy))+'px';float.style.right='auto';float.style.bottom='auto'});const grass=document.createElement('button');grass.id='wdea-grass-handle';grass.type='button';grass.setAttribute('aria-label','WDEA AI visszahívása');grass.innerHTML='<span aria-hidden="true">🌿</span><b>❮</b>';document.body.append(grass);function park(){close();float.classList.add('wdea-edge-away');document.body.classList.add('wdea-robot-parked')}function unpark(){float.classList.remove('wdea-edge-away');document.body.classList.remove('wdea-robot-parked')}grass.addEventListener('click',unpark);float.addEventListener('dblclick',park);float.addEventListener('pointerup',e=>{if(dragged){const r=float.getBoundingClientRect();if(r.left<24||r.right>innerWidth-24){setTimeout(park,160)}}});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&panel.classList.contains('open'))close()});const observer=new MutationObserver(()=>{const active=!!document.querySelector('dialog[open], [role="dialog"][aria-modal="true"], .lightbox.open, .modal.open, .image-viewer.open');document.body.classList.toggle('wdea-media-open',active);if(active&&!document.body.classList.contains('wdea-robot-parked'))park()});observer.observe(document.body,{attributes:true,childList:true,subtree:true,attributeFilter:['class','open','aria-modal']});window.WDEA_WORK_AI={open,close,send,say,hide:park,show:unpark};render();})();